WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (176::BIGINT, 'Profesor regular. No se aprende mucho. Es un curso que se aprueba con la asistencia. Los trabajos suelen ser grupales y el resto son forms.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2026-07-09T00:00:00+00:00'::TIMESTAMPTZ, 'f892bd67c020555c1f44ebcd93b836c0834aa648d1b5ae1aa120ad863f6e60ea'::TEXT, ARRAY[502]::BIGINT[]),
    (176::BIGINT, 'Profe tranquilo y muy pura vida. El curso es bastante fácil y las clases son cortas. Nada más una exposición y un trabajo final donde hay que dedicarle un toque de tiempo al curso, pero son evaluaciones grupales. Con ir a clase y trabajar con su grupo se pasa sin ningún problema.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2026-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'fc4c8d5fae67cbd7c8809ebb7781c77f44cfcb4b4565b5085bdb3b8b7d8643b9'::TEXT, ARRAY[502]::BIGINT[]),
    (176::BIGINT, 'Las clases son super aburridas pero se pasa super fácil, el profe es buena nota'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-12-25T00:00:00+00:00'::TIMESTAMPTZ, 'a1dd3a3efd83e8a8f69245d0ef22e1b57a2dc58eaf2b81840b68054343b074ef'::TEXT, ARRAY[894]::BIGINT[]),
    (176::BIGINT, 'El curso más aburrido que va a llevar en su vida. El profe es buena gente y le interesa la materia, pero eso no significa que lo explique o lo haga interesante. Si no quiere hacer nada durante 2 horas al día, esta es su opción.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-07-21T00:00:00+00:00'::TIMESTAMPTZ, '1a7a115d889496b97efd33f60bcb9a1ab0ed98beafce8c5415ca8c268bc6b9ea'::TEXT, ARRAY[502]::BIGINT[]),
    (176::BIGINT, 'El profe no es malo, pero si algo desordenado pero para el tipo de curso está bien. Deja varios trabajos por lo que hay que dedicarle algo de tiempo fuera de clase, pero nada muy extravagante. No es mala opción, pero creo que el Vinicio es más chill y menos bretes.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2025-06-27T00:00:00+00:00'::TIMESTAMPTZ, '928e596c739a872da6056db551a991794e274c4be1227f6004bfeb57cd6ad79d'::TEXT, ARRAY[502]::BIGINT[]),
    (176::BIGINT, 'El mae es buena gente pero llega tarde a clases, a veces le vale mird las cosas, es desordenado conforme a fechas y se inventa trabajos conforme avanza el curso(no tiene claro que evaluar). El TecDigital lo actualiza cuando le da la gana.fácil pero aburrid, mucho trabajo ojalá enseñar instrumentos'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Muchos proyectos grupales']::TEXT[], '2025-06-24T00:00:00+00:00'::TIMESTAMPTZ, '809224f50fa918bcd77d54819c7510a886ed8f0d16976873f822ff059c3cc20c'::TEXT, ARRAY[502]::BIGINT[]),
    (176::BIGINT, 'Es un curso mmuy sencillo, si faltas a clase virtual el profe deja las grabaciones y te pone a realizar un resummen de página y media de la clase para que no pierdas inmediatamente el CFH, a veces tal vez puede ser un poquito aburrido porque el profe habla tranquilo y bajo, pero es muy buena gente'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-09-24T00:00:00+00:00'::TIMESTAMPTZ, '273a8985913e05ecee97226d79d45e416e89c4fb1b10e0b92e2b0a13b817ea28'::TEXT, ARRAY[894]::BIGINT[]),
    (176::BIGINT, 'Curso muy fácil, los trabajos que deja se hacen súper rápido y el profe es pura vida.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra']::TEXT[], '2024-06-17T00:00:00+00:00'::TIMESTAMPTZ, '696c7d44db9480cd1c784b16bf07675263ab9a17daf27e475c3f7d9134ca9174'::TEXT, ARRAY[502]::BIGINT[]),
    (176::BIGINT, 'El profe es muy pura vida. El curso no fue ni pesado ni difícil. No dude en matricular con él.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Clases largas']::TEXT[], '2023-01-26T00:00:00+00:00'::TIMESTAMPTZ, 'de7278c1367daf0aa21e18580ceeff93ca776ae31575c3f46081de4e7df58bca'::TEXT, ARRAY[502]::BIGINT[]),
    (176::BIGINT, 'El tema del CFH es interesante y el profesor sabe mucho del tema. Es un CFH fácil y casi no deja trabajos para la casa. Además esos trabajos son muy sencillos, casi todo se hace presencial. El profesor es amable y respetuoso pero se lo come un poco la tecnología. Súper recomendado.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Clases excelentes']::TEXT[], '2021-08-21T00:00:00+00:00'::TIMESTAMPTZ, '0cd2a461c51b782d7632dbe5d095cf313d012a077caca099aabf01df695c3116'::TEXT, ARRAY[894]::BIGINT[]),
    (176::BIGINT, 'Es demasiado desordenado para calificar y se inventa los trabajos conforme avanza el semestre. No sabe usar bien TecDigital. Es fácil pero no se aprende absolutamente nada.'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-20T00:00:00+00:00'::TIMESTAMPTZ, '217570430cf715480d262171d441a8674dd3561287f99c4200a906c9e52942eb'::TEXT, ARRAY[502]::BIGINT[]),
    (176::BIGINT, 'Hay que conectarse casi que todas las semanas son buenos temas. sí hay que participar y atiende bien las consultas. los temas los trabajos no quitan tanto tiempo'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Respetado por los estudiantes']::TEXT[], '2021-06-21T00:00:00+00:00'::TIMESTAMPTZ, '33ae648e44c6ee4cf4416d06085f2cba3694c6399ec9dd85adc50c4ebdfe580e'::TEXT, ARRAY[502]::BIGINT[]),
    (176::BIGINT, 'para pasar la cultural está bien. no se aprende nada, pero el profe le ayuda a meterse a grupos musicales y todo eso por si le interesa. solo calificó un trabajo enserio'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases largas', 'Brinda apoyo']::TEXT[], '2021-06-20T00:00:00+00:00'::TIMESTAMPTZ, '6b95b950082086b8b54089c60a7b42adf8623dc2bb46592a69500f5f219015fe'::TEXT, ARRAY[502]::BIGINT[]),
    (176::BIGINT, 'Es muy desordenado para calificar y se inventa los trabajos conforme avanza el semestre.'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-11T00:00:00+00:00'::TIMESTAMPTZ, '1afb4640401bdb7ec723a2e40403c3f3cf6baf1692a9981f1f13522ed7c06184'::TEXT, ARRAY[502]::BIGINT[]),
    (176::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-02-06T00:00:00+00:00'::TIMESTAMPTZ, '51000ae0160abb9820c1a5c65041ce1f32fd51f582e68e94082102b06c1897b3'::TEXT, ARRAY[502]::BIGINT[]),
    (176::BIGINT, 'El profe es desordenado con su método. Habla de temas musicales asumiendo que todos saben de música, y en general no es claro con las ideas que quiere transmitir. Alterna entre clases sincrónicas y asincrónicas, y deja trabajos fáciles pero aburridos. Mejor busque otra opción...'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2021-02-01T00:00:00+00:00'::TIMESTAMPTZ, '8a29c8960c383c86ba8fbb7a685609ede2efa56eab2371c25675f072a202ed6a'::TEXT, ARRAY[502]::BIGINT[]),
    (176::BIGINT, '(modalidad virtual) El curso resultó muy aburrido, lo que se aprende de música es poco y muy disperso, actividades poco interesantes. Sumamente fácil.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2021-01-28T00:00:00+00:00'::TIMESTAMPTZ, 'bffe36a767c5d14a1c8943329158c11d9f3a87e6eb1fee367d57a438ed27b080'::TEXT, ARRAY[502]::BIGINT[]),
    (176::BIGINT, 'Realmente hace el curso muy fácil, pero se simplifica tanto que no se aprende mucho. Si solo quiere pasar la cultural matricule con él, si la quiere disfrutar más, no lo recomiendo.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2020-08-11T00:00:00+00:00'::TIMESTAMPTZ, '6bd4696306b27f131aca5600c9f319095d7b358091aaa5c43f42a2547765ed29'::TEXT, ARRAY[502]::BIGINT[]),
    (176::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Da crédito extra']::TEXT[], '2019-12-02T00:00:00+00:00'::TIMESTAMPTZ, 'aa922238685d9fee6fbbb5d6a5de7a4246850aaeb812b3fe828288091800220f'::TEXT, ARRAY[512]::BIGINT[]),
    (176::BIGINT, 'A él se le olvida que el curso vale 0 créditos y deja muchos trabajos.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2019-04-29T00:00:00+00:00'::TIMESTAMPTZ, '5b16a288b8b831a7703bfc2af02d2fd2de6e6cceef6ee7f26b3f44aa02483f1d'::TEXT, ARRAY[512]::BIGINT[]),
    (176::BIGINT, 'La clase es aburrida pero el curso en si es muy facil. Deja un par de trabajos y un informe de los conciertos nada mas.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-29T00:00:00+00:00'::TIMESTAMPTZ, '83d0564c632a3e06e0883f39829648f223cf16b447f72fae108d2f7fb28f91aa'::TEXT, ARRAY[502]::BIGINT[]),
    (176::BIGINT, 'Súper recomendado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-07T00:00:00+00:00'::TIMESTAMPTZ, 'd7cd346a3dc497c4ab0a8def7970c9a465df9d79dff34fe2d6598690f2dae5c9'::TEXT, ARRAY[502]::BIGINT[]),
    (176::BIGINT, 'Super buen profe, demasiado interesante sus clases. Lo recomiendo 100%'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-11-17T00:00:00+00:00'::TIMESTAMPTZ, '2b98518019fedb4d02ebdf6d9f8085b694b3f15a19bc2ba198883587f6138ccf'::TEXT, ARRAY[502]::BIGINT[]),
    (176::BIGINT, 'Da la clase muy bien y deja algunas exposiciones y un ensayo al final pero se pasa fácil. Es buena gente.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-16T00:00:00+00:00'::TIMESTAMPTZ, '8206b2938be44c055ba8b5d2ea120bd15eb8213eaa9def75588a35f252be4045'::TEXT, ARRAY[502]::BIGINT[]),
    (176::BIGINT, 'Se pasa fácil, pero las clases son muy aburridas, no deja trabajos, solo un reporte al final. Cuando hay concierto, no hay clase (esa semana).'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-06T00:00:00+00:00'::TIMESTAMPTZ, '6ca34c29d7c4ffaa090cb0d195379a48a0c4bb3038e0be52cf0f5c56d1c89945'::TEXT, ARRAY[502]::BIGINT[]),
    (176::BIGINT, 'Le gusta complicar el curso que deberia ser sencillo'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'bf5eb9c68ecfa3682fe49cceead2444f88bcf4813c0b85b038ed1c69fa0b31c1'::TEXT, ARRAY[512]::BIGINT[]),
    (176::BIGINT, 'Se pasa facil , casi no se hace nada en el curso'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-20T00:00:00+00:00'::TIMESTAMPTZ, 'f3e82510f42a60b44f7cf387742eeb6790107db134876f5fe54215997f5fcf1e'::TEXT, ARRAY[512]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
